def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(max(0.0, min(budget, 18.0)))

    opp_bids = []
    bob_like_bids = []
    pressure_bids = []
    desperate_count = 0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            opp_bids.append(float(bid))
            if float(bid) <= 95:
                bob_like_bids.append(float(bid))
            if float(bid) >= 110:
                pressure_bids.append(float(bid))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    avg_prev = sum(opp_bids) / len(opp_bids) if opp_bids else 95.0
    low_anchor = max(bob_like_bids) if bob_like_bids else 84.0
    high_pressure = max(pressure_bids) if pressure_bids else max(opp_bids) if opp_bids else 100.0

    units = supply / float(WATER_REQ)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(96.0, low_anchor + 8.0, DAILY_SALARY * 1.28))
        return float(max(0.0, bid))

    if hp <= 4 or no_water >= 1:
        if units >= 1.8:
            bid = max(72.0, low_anchor + 1.5)
        else:
            bid = max(88.0, low_anchor + 4.0)
        if desperate_count >= 2:
            bid = max(bid, 96.0)
        return float(max(0.0, min(budget, bid)))

    if units >= 1.8:
        bid = 24.0
        if avg_prev < 90:
            bid = max(bid, low_anchor + 1.0)
        return float(max(0.0, min(budget, bid)))

    if units >= 1.45:
        bid = max(58.0, low_anchor + 2.0)
        if desperate_count >= 2:
            bid += 6.0
        return float(max(0.0, min(budget, bid)))

    bid = max(82.0, low_anchor + 3.0)
    if high_pressure >= 140 and hp >= 6 and no_water == 0:
        bid = min(bid, 86.0)
    elif desperate_count >= 2:
        bid = max(bid, 92.0)

    if day >= 8 and hp >= 6:
        bid = min(bid, 84.0)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    alive_prev = []
    for opp_id, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append(b_val)
            alive_prev.append((opp_id, b_val))

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_b = sorted(yesterday_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Estimate how many water units might be needed from supply context
    # (We don't know exact allocation rule; still use supply to scale bid aggressiveness.)
    # More supply => less aggressive.
    supply_factor = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_factor = max(0.0, min(1.0, supply_factor))

    # Base bid: aim to be competitive but not wasteful.
    base = DAILY_SALARY * (0.45 - 0.15 * supply_factor)

    # If I'm in danger of running out of water, bid more.
    danger = 0
    if my_hp <= 2.0:
        danger = 2
    elif my_hp <= 4.0 or my_no_water_days >= 2:
        danger = 1

    # If opponents were bidding high yesterday, increase to avoid being priced out.
    # Cindy/Eric were around ~116 avg in the meta-round context.
    high_pressure = 1 if highest_prev_bid >= DAILY_SALARY * 0.85 else 0

    if high_pressure:
        if danger == 2:
            bid = max(base, highest_prev_bid * 0.95)
        elif danger == 1:
            bid = max(base, highest_prev_bid * 0.75)
        else:
            # Slightly under the highest to save budget; still enough to compete.
            bid = max(base, second_prev_bid * 0.9 if second_prev_bid > 0 else highest_prev_bid * 0.6)
    else:
        # If nobody bid extremely high, stay conservative.
        if danger == 2:
            bid = max(base, DAILY_SALARY * 0.75)
        elif danger == 1:
            bid = max(base, DAILY_SALARY * 0.6)
        else:
            bid = base

    # Budget safety and non-negative
    bid = float(bid)
    if my_budget <= 0:
        return 0.0

    # Cap bid to avoid overspending early; but allow higher if very low hp.
    cap = my_budget
    if danger == 0:
        cap = min(cap, DAILY_SALARY * 0.7)
    elif danger == 1:
        cap = min(cap, DAILY_SALARY * 0.9)
    else:
        cap = min(cap, DAILY_SALARY * 1.05)

    bid = max(0.0, min(bid, cap, my_budget))
    return bid
